// === Tab: mySketch ===
let num = 500; // Number of particles
let particles = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();

  for (let i = 0; i < num; i++) {
    let loc = createVector(random(width), random(height));
    particles.push(new Particle(loc));
  }
}

function draw() {
  background(0, 20); // Slightly transparent background to create trails

  for (let particle of particles) {
    particle.update();
    particle.display();
  }
}

class Particle {
  constructor(loc) {
    this.pos = loc.copy();
    this.vel = p5.Vector.random2D().mult(random(1, 4)); // Random initial velocity
    this.acc = createVector();
    this.trail = [];
    this.maxTrailLength = 100; // Maximum length of the particle trail
  }

  update() {
    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
    this.edges();
    this.trail.push(this.pos.copy());

    if (this.trail.length > this.maxTrailLength) {
      this.trail.splice(0, 1); // Remove oldest trail point
    }
  }

  edges() {
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.y < 0) this.pos.y = height;
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.y > height) this.pos.y = 0;
  }

  display() {
    beginShape();
    for (let i = 0; i < this.trail.length; i++) {
      let alpha = map(i, 0, this.trail.length, 0, 255);
      fill(255, alpha);
      ellipse(this.trail[i].x, this.trail[i].y, 8, 8);
    }
    endShape();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

